/* From Uiverse.io by Gaurav-WebDev - Tags: button, hover effect, cool btn */
.__UIV_SCOPE__ .button {
  height: 50px;
  width: 150px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: all 0.5s ease-in-out;
}

.__UIV_SCOPE__ .button:hover {
  box-shadow: .5px .5px 150px #252525;
}

.__UIV_SCOPE__ .type1::after {
  content: "Thanks";
  height: 50px;
  width: 150px;
  background-color: #008080;
  color: #fff;
  position: absolute;
  top: 0%;
  left: 0%;
  transform: translateY(50px);
  font-size: 1.2rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.5s ease-in-out;
}

.__UIV_SCOPE__ .type1::before {
  content: "Hover Me";
  height: 50px;
  width: 150px;
  background-color: #fff;
  color: #008080;
  position: absolute;
  top: 0%;
  left: 0%;
  transform: translateY(0px) scale(1.2);
  font-size: 1.2rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.5s ease-in-out;
}

.__UIV_SCOPE__ .type1:hover::after {
  transform: translateY(0) scale(1.2);
}

.__UIV_SCOPE__ .type1:hover::before {
  transform: translateY(-50px) scale(0) rotate(120deg);
}
